// Mode: Run Once for Each Item
// Input: the ERPNext style template ({ data: {...} }). Builds the Shopify lookup (by the
// first size's SKU) and the multi-variant productSet request.
// ---- lib/product-model.js -------------------------------------------------
// Product model v2: real Little Sleepies SKU structure + launch critical path.
// Python twin for the SKU rules: python/ls_integrations/product_model.py.
// The line below is replaced at build time with the contents of shared/product_model.json,
// available here as PRODUCT_MODEL (divisions, size codes, compliance profiles, milestones).
const PRODUCT_MODEL = {"_comment":"Product model v2: one source of truth for the JS (n8n, inlined at build time) and Python code. Division letters, size labels and size codes were observed on the public littlesleepies.com product feed (Oct 2026). Compliance requirements and milestone lead times are a SIMPLIFIED model for the POC: the real matrix belongs to Compliance & Integrity and the real calendar to Production.","divisions":{"Sleep":{"code":"S","fabric":"Lunaluxe"},"Play":{"code":"D","fabric":"Soluxe"},"Other":{"code":"O","fabric":null}},"sizeCodes":{"S":[{"label":"Preemie","code":"10","sort":1,"ageGroup":"Baby"},{"label":"Newborn","code":"11","sort":2,"ageGroup":"Baby"},{"label":"0-3 months","code":"01","sort":3,"ageGroup":"Baby"},{"label":"3-6 months","code":"02","sort":4,"ageGroup":"Baby"},{"label":"6-12 months","code":"03","sort":5,"ageGroup":"Baby"},{"label":"12-18 months","code":"04","sort":6,"ageGroup":"Baby"},{"label":"18-24 months","code":"05","sort":7,"ageGroup":"Baby"},{"label":"2T","code":"12","sort":8,"ageGroup":"Toddler"},{"label":"3T","code":"08","sort":9,"ageGroup":"Toddler"},{"label":"4T","code":"14","sort":10,"ageGroup":"Toddler"},{"label":"5/6","code":"15","sort":11,"ageGroup":"Kid"},{"label":"7/8","code":"16","sort":12,"ageGroup":"Kid"},{"label":"9/10","code":"23","sort":13,"ageGroup":"Kid"},{"label":"12/14","code":"24","sort":14,"ageGroup":"Kid"},{"label":"16","code":"25","sort":15,"ageGroup":"Kid"},{"label":"XS","code":"22","sort":16,"ageGroup":"Adult"},{"label":"S","code":"17","sort":17,"ageGroup":"Adult"},{"label":"M","code":"18","sort":18,"ageGroup":"Adult"},{"label":"L","code":"19","sort":19,"ageGroup":"Adult"},{"label":"XL","code":"20","sort":20,"ageGroup":"Adult"},{"label":"XXL","code":"21","sort":21,"ageGroup":"Adult"},{"label":"3XL","code":"32","sort":22,"ageGroup":"Adult"},{"label":"Large","code":"27","sort":23,"ageGroup":"One Size"},{"label":"Newborn - 3T","code":"29","sort":24,"ageGroup":"One Size"}],"D":[{"label":"0-3 months","code":"34","sort":1,"ageGroup":"Baby"},{"label":"3-6 months","code":"35","sort":2,"ageGroup":"Baby"},{"label":"6-12 months","code":"36","sort":3,"ageGroup":"Baby"},{"label":"12-18 months","code":"37","sort":4,"ageGroup":"Baby"},{"label":"18-24 months","code":"38","sort":5,"ageGroup":"Baby"}],"O":[{"label":"One Size","code":"26","sort":1,"ageGroup":"One Size"}]},"complianceProfiles":{"Children's Sleepwear":["Lead (CPSIA)","Phthalates (CPSIA)","Snug-Fit Dimensions (16 CFR 1615/1616)","Tracking Label","Children's Product Certificate"],"Children's Apparel":["Lead (CPSIA)","Flammability (16 CFR 1610)","Tracking Label","Children's Product Certificate"],"Children's Accessory":["Lead (CPSIA)","Tracking Label","Children's Product Certificate"],"Adult Apparel":["Flammability (16 CFR 1610)"]},"milestones":[{"key":"sample","label":"Pre-production sample approved","team":"Production","daysBeforeLaunch":90},{"key":"license","label":"Licensor approval","team":"Product","daysBeforeLaunch":75,"licensedOnly":true},{"key":"compliance","label":"Compliance tests passed","team":"Compliance & Integrity","daysBeforeLaunch":60},{"key":"photo","label":"Photography delivered","team":"Photography","daysBeforeLaunch":30},{"key":"erp","label":"Synced to the ERP","team":"Systems","daysBeforeLaunch":21}],"atRiskWindowDays":7};
// DIVISION-STYLE-COLORWAY[-SIZE], e.g. S-0108-0665-10 (Sleep, Zippy, colorway 0665, Preemie).
// The colorway number is per style: the same print has a different number on each style.
// Pattern: S, D or O, then 4 digits, then 4 digits, then optionally 2 more digits for the size.
const SKU_PATTERN = /^([SDO])-(\d{4})-(\d{4})(?:-(\d{2}))?$/;

// Turn a division letter (e.g. "S") into its name (e.g. "Sleep"), or null if unknown.
function divisionByCode(code) {
  return Object.keys(PRODUCT_MODEL.divisions).find((d) => PRODUCT_MODEL.divisions[d].code === code) || null;
}

// Build the colorway SKU (e.g. "S-0108-0665") from its parts. Returns null if any part is bad.
function buildSkuBase({ division, styleNumber, colorwayNumber }) {
  // The division's settings (including its letter code).
  const d = PRODUCT_MODEL.divisions[division];
  // Style and colorway numbers as text with spaces trimmed.
  const style = String(styleNumber ?? '').trim();
  const colorway = String(colorwayNumber ?? '').trim();
  // Unknown division, or a number that isn't exactly 4 digits? Can't build a SKU.
  if (!d || !/^\d{4}$/.test(style) || !/^\d{4}$/.test(colorway)) return null;
  // Join the parts with dashes.
  return `${d.code}-${style}-${colorway}`;
}

// Split a SKU into its parts. Returns null if it isn't a valid SKU.
function parseSku(sku) {
  // Check the SKU against the pattern; m holds the matched pieces.
  const m = String(sku ?? '').trim().match(SKU_PATTERN);
  // Didn't match the pattern.
  if (!m) return null;
  // m[1] = division letter, m[2] = style, m[3] = colorway, m[4] = size code (may be missing).
  return { divisionCode: m[1], division: divisionByCode(m[1]), style: m[2], colorway: m[3], sizeCode: m[4] || null };
}

// Variant SKUs for a size run. Size codes depend on the division (0-3 months is 01 in Sleep, 34 in Play).
function sizeRunSkus(skuBase, sizeLabels) {
  // Split the colorway SKU into its parts.
  const parsed = parseSku(skuBase);
  // That division's list of sizes and their codes (empty list if unknown).
  const table = parsed ? PRODUCT_MODEL.sizeCodes[parsed.divisionCode] || [] : [];
  // Sizes we found a code for.
  const variants = [];
  // Sizes we couldn't find a code for.
  const unknown = [];
  // Look up each size label.
  for (const label of sizeLabels || []) {
    const size = table.find((s) => s.label === label);
    // Found: add the full SKU, e.g. "S-0108-0665-10".
    if (size) variants.push({ size: label, sku: `${skuBase}-${size.code}`, sort: size.sort });
    // Not found: note it.
    else unknown.push(label);
  }
  // Put the sizes in their natural order (smallest first).
  variants.sort((a, b) => a.sort - b.sort);
  return { variants, unknown };
}

// Turn a size code (e.g. "10") into its label (e.g. "Preemie"). Falls back to the code.
function sizeLabelFor(divisionCode, sizeCode) {
  const size = (PRODUCT_MODEL.sizeCodes[divisionCode] || []).find((s) => s.code === sizeCode);
  return size ? size.label : sizeCode;
}

// ERPNext Item Attribute per division: the same label has different codes per division
// (0-3 months = 01 in Sleep, 34 in Play), and an attribute value can only have one abbreviation.
function sizeAttributeName(division) {
  // e.g. "Size (Sleep)".
  return `Size (${division})`;
}

// Accepts 18.5, "18.50", "$1,204.99". Returns a 2-dp number, or null if not a positive amount.
function parseCost(raw) {
  // Nothing given.
  if (raw === null || raw === undefined) return null;
  // Numbers stay as they are; text has "$", commas and spaces removed.
  const cleaned = typeof raw === 'number' ? raw : String(raw).replace(/[$,\s]/g, '');
  // Empty, or not a plain number like "12" or "12.50"? Reject it.
  if (cleaned === '' || !/^-?\d*\.?\d+$/.test(String(cleaned))) return null;
  // Convert to a number.
  const n = Number(cleaned);
  // Must be a real number above zero.
  if (!Number.isFinite(n) || n <= 0) return null;
  // Round to cents.
  return Math.round(n * 100) / 100;
}

// ---- colorway → ERP template + size variants (LS-01) ----------------------
// lookups: Maps of Airtable record id → fields for Style Master, Prints and Size Codes.
// The template's item_code is the SKU base; ERPNext names each variant
// template-code + "-" + attribute abbreviation, i.e. exactly S-0108-0665-10.
function transformColorway({ recordId, fields = {} }, { styles, prints, sizeCodes }) {
  // Every problem found. If this stays empty, the colorway is valid.
  const errors = [];
  // The linked style and print (first linked ID), or null if none.
  const style = styles.get((fields.Style || [])[0]) || null;
  const print = prints.get((fields.Print || [])[0]) || null;
  // The colorway name with spaces trimmed.
  const name = String(fields.Colorway || '').trim();

  // Basic checks: approved, compliance passed, and has a name, style and print.
  if (fields['Production Status'] !== 'Approved for Production') errors.push(`Production Status is "${fields['Production Status'] || ''}", expected "Approved for Production"`);
  if (fields['Compliance Status'] !== 'Passed') errors.push(`Compliance Status is "${fields['Compliance Status'] || 'not computed'}": every required test must pass first (see the Critical Path field)`);
  if (!name) errors.push('Colorway name is required');
  if (!style) errors.push('No style linked');
  if (!print) errors.push('No print linked');

  // The division comes from the style (e.g. "Sleep").
  const division = style ? style.Division : null;
  // Build the colorway SKU from the division, style number and colorway number.
  const skuBase = style ? buildSkuBase({ division, styleNumber: style['Style Number'], colorwayNumber: fields['Colorway Number'] }) : null;
  // Couldn't build it? The colorway number must be wrong.
  if (style && !skuBase) errors.push(`Colorway Number "${fields['Colorway Number'] || ''}" must be 4 digits`);
  // Check the fabric is the right one for this division.
  if (style && style.Fabric && !fabricMatchesDivision(division, style.Fabric)) errors.push(`${division} styles should be ${PRODUCT_MODEL.divisions[division].fabric}, not ${style.Fabric}`);

  // The style's sizes: turn each linked size ID into its record, dropping any not found.
  const runRows = style ? (style['Size Run'] || []).map((id) => sizeCodes.get(id)).filter(Boolean) : [];
  // Any sizes that belong to a different division (a data mistake).
  const wrongDivision = runRows.filter((s) => s.Division !== division).map((s) => s['Size Label']);
  // No sizes at all.
  if (style && !runRows.length) errors.push(`Style ${style['Style Number']} has no Size Run`);
  // Sizes from the wrong division.
  if (wrongDivision.length) errors.push(`Size Run includes ${division ? 'non-' + division : 'mismatched'} sizes: ${wrongDivision.join(', ')}`);
  // The correct sizes, in their sort order, as labels (e.g. ["Preemie", "Newborn", …]).
  const sizes = runRows.filter((s) => s.Division === division).sort((a, b) => a['Sort Order'] - b['Sort Order']).map((s) => s['Size Label']);
  // Check every size has a size code.
  const { unknown } = skuBase ? sizeRunSkus(skuBase, sizes) : { unknown: [] };
  if (unknown.length) errors.push(`No size code for ${unknown.join(', ')} in division ${division}`);

  // Cost and retail prices as clean numbers (null if bad).
  const cost = parseCost(fields['Cost Price']);
  const retail = style ? parseCost(style['Retail Price']) : null;
  // Launch date as "YYYY-MM-DD", or null.
  const launch = fields['Launch Date'] ? String(fields['Launch Date']).slice(0, 10) : null;
  // Price and date checks.
  if (cost === null) errors.push('Cost Price must be a positive amount');
  if (style && retail === null) errors.push(`Style ${style['Style Number']} needs a Retail Price`);
  if (!launch) errors.push('Launch Date is required');

  // Valid if no problems were found.
  const valid = errors.length === 0;
  // The ERP size attribute for this division, e.g. "Size (Sleep)".
  const attribute = division ? sizeAttributeName(division) : null;
  // Fields shared by "create" and "update" (only built when valid).
  const common = valid ? {
    // Name cut to 140 characters (ERPNext's limit).
    item_name: name.slice(0, 140),
    item_group: division,
    brand: 'Little Sleepies',
    // "<Print Name> <Style Name>. <Fiber Content>".
    description: `${print['Print Name']} ${style['Style Name']}. ${style['Fiber Content'] || ''}`.trim(),
    valuation_rate: cost,
    // Links back to Airtable so we can find this item again (keeps the sync idempotent).
    custom_airtable_record_id: recordId,
    // The rest are custom fields copied from the style, print and colorway.
    custom_style_id: style['Style Number'],
    custom_colorway_number: String(fields['Colorway Number']).trim(),
    custom_print_name: print['Print Name'],
    custom_print_family: print.Slug || null,
    custom_print_category: print['Print Category'] || null,
    custom_product_type: style['Product Type'] || null,
    custom_fabric_type: style.Fabric || null,
    custom_fiber_content: style['Fiber Content'] || null,
    custom_compliance_profile: style['Compliance Profile'] || null,
    custom_launch_date: launch,
    // Merch date, or the launch date if there isn't one.
    custom_merch_date: fields['Merch Date'] ? String(fields['Merch Date']).slice(0, 10) : launch,
    custom_inventory_tier: fields['Inventory Tier'] ?? null,
    // ERPNext checkboxes use 1/0, not true/false.
    custom_limited_edition: fields['Limited Edition'] ? 1 : 0,
    custom_purchase_limit: fields['Purchase Limit'] ?? null,
    custom_retail_price: retail,
    // Sizes stored as one text field, e.g. "Preemie|Newborn|0-3 Months".
    custom_size_run: sizes.join('|'),
  } : null;

  return {
    recordId,
    colorwayName: name,
    skuBase,
    valid,
    errors,
    sizes,
    approvedAt: null,
    // Template-only fields can't change once variants exist, so updates send `common` only.
    // Full payload for creating a new style template (null if invalid).
    templatePayload: valid ? {
      item_code: skuBase, stock_uom: 'Nos', is_stock_item: 1, is_purchase_item: 1, is_sales_item: 1,
      has_variants: 1, variant_based_on: 'Item Attribute', attributes: [{ attribute }], ...common,
    } : null,
    // Payload for updating an existing template.
    updatePayload: common,
    // erpnext.controllers.item_variant.enqueue_multiple_variant_creation expects args as a JSON string.
    // Request asking ERPNext to create one variant per size (null if invalid).
    variantRequest: valid ? { item: skuBase, args: JSON.stringify({ [attribute]: sizes }) } : null,
  };
}

// The list of compliance tests a profile requires, or null if the profile is unknown.
function requiredTests(profile) {
  return PRODUCT_MODEL.complianceProfiles[profile] || null;
}

// true if the fabric is the one this division expects (or the division has no rule).
function fabricMatchesDivision(division, fabric) {
  const expected = (PRODUCT_MODEL.divisions[division] || {}).fabric;
  return !expected || expected === fabric;
}

// ---- dates (date-only, UTC) ----------------------------------------------
// Add (or with a negative number, subtract) days from a "YYYY-MM-DD" date.
function addDaysIso(iso, days) {
  // Midnight UTC on that date, so time zones can't shift the day.
  const d = new Date(`${String(iso).slice(0, 10)}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  // Back to "YYYY-MM-DD".
  return d.toISOString().slice(0, 10);
}
// Number of days from one date to another (negative if "to" is earlier). 86400000 = ms in a day.
function daysBetween(fromIso, toIso) {
  return Math.round((Date.parse(`${toIso.slice(0, 10)}T00:00:00Z`) - Date.parse(`${fromIso.slice(0, 10)}T00:00:00Z`)) / 86400000);
}
// The latest date in a list (ignoring blanks), or null. "YYYY-MM-DD" dates sort correctly as text.
const maxDate = (dates) => dates.filter(Boolean).map((d) => String(d).slice(0, 10)).sort().pop() || null;

// ---- critical path --------------------------------------------------------
// Late = past due and not done. A blocked milestone (failed test, rejected sample) is only
// "late" once it's past due; before that it's a risk. Shared by the timeline and the digest.
const isLate = (m) => m.status === 'open_late' || (m.status === 'blocked' && m.daysLate > 0);
// Inputs are Airtable `fields` objects. Returns the Colorway fields to write back and one
// row per milestone (for the warehouse snapshot and the team digest).
function computeCriticalPath({ colorway, style, print, samples = [], tests = [], shots = [], today }) {
  // Data problems found along the way.
  const issues = [];
  if (!style) issues.push('No style linked');
  if (!print) issues.push('No print linked');
  // Build the colorway SKU (null if we can't).
  const skuBase = style
    ? buildSkuBase({ division: style.Division, styleNumber: style['Style Number'], colorwayNumber: colorway['Colorway Number'] })
    : null;
  // Have a style but no SKU? The colorway number must be wrong.
  if (style && !skuBase) issues.push(`Colorway Number "${colorway['Colorway Number'] ?? ''}" must be 4 digits (style ${style['Style Number']}, ${style.Division})`);
  // Wrong fabric for the division.
  if (style && style.Fabric && !fabricMatchesDivision(style.Division, style.Fabric)) {
    issues.push(`${style.Division} styles should be ${PRODUCT_MODEL.divisions[style.Division].fabric}, not ${style.Fabric}`);
  }

  // Sample: the pre-production (PP) sample approval is the gate.
  // Only the pre-production samples.
  const pp = samples.filter((s) => s.Round === 'Pre-Production');
  // An approved one, if any.
  const ppApproved = pp.find((s) => s.Status === 'Approved');
  // The most recent one (sorted by decision date, take the last). slice() copies so the original isn't reordered.
  const ppLatest = pp.slice().sort((a, b) => String(a['Decision Date'] || '').localeCompare(String(b['Decision Date'] || ''))).pop();
  // Overall sample status.
  const sampleStatus = ppApproved ? 'Approved' : samples.length ? 'In Progress' : 'Not Started';

  // Compliance: every test the style's profile requires must be Passed (or Not Applicable).
  // The tests this style needs.
  const required = style ? requiredTests(style['Compliance Profile']) : null;
  if (style && !required) issues.push(`Unknown Compliance Profile "${style['Compliance Profile'] ?? ''}"`);
  // Helper: the most recent test of one type (by result date, or submitted date if no result yet).
  const latestOfType = (type) => tests.filter((t) => t['Test Type'] === type)
    .sort((a, b) => String(a['Result Date'] || a['Submitted Date'] || '').localeCompare(String(b['Result Date'] || b['Submitted Date'] || ''))).pop();
  // For each required test type, its latest test (may be missing).
  const perType = (required || []).map((type) => ({ type, test: latestOfType(type) }));
  // Test types whose latest result failed.
  const failed = perType.filter((p) => p.test && p.test.Status === 'Failed').map((p) => p.type);
  // Test types not yet passed (missing, pending or failed).
  const missing = perType.filter((p) => !p.test || !['Passed', 'Not Applicable'].includes(p.test.Status)).map((p) => p.type);
  // Overall compliance status.
  const complianceStatus = !tests.length ? 'Not Started' : failed.length ? 'Failed' : required && !missing.length ? 'Passed' : 'In Testing';

  // Photography: at least one shot, all delivered.
  const photoDone = shots.length > 0 && shots.every((s) => s.Status === 'Delivered');
  const photoStatus = photoDone ? 'Complete' : shots.length ? 'In Progress' : 'Not Started';

  // Licensed prints need an extra licensor approval milestone.
  const licensed = Boolean(print && print.License === 'Licensed');
  // Launch date as "YYYY-MM-DD", or null.
  const launch = colorway['Launch Date'] ? String(colorway['Launch Date']).slice(0, 10) : null;

  // For each milestone: is it done, when, is it blocked, and any extra note.
  const state = {
    // Sample: done when a PP sample is approved; blocked if the latest one was rejected.
    sample: { done: Boolean(ppApproved), completedOn: ppApproved && ppApproved['Decision Date'],
      blocked: !ppApproved && ppLatest && ppLatest.Status === 'Rejected' ? 'Last PP sample rejected: new round needed' : null },
    // License: done when the licensor approves; blocked if they asked for changes.
    license: { done: print && print['Licensor Approval'] === 'Approved', completedOn: print && print['Licensor Approval Date'],
      blocked: print && print['Licensor Approval'] === 'Changes Requested' ? 'Licensor requested changes' : null },
    // Compliance: done when all tests pass (date = last pass); blocked if any failed; note lists what's still waiting.
    compliance: { done: complianceStatus === 'Passed', completedOn: maxDate(tests.filter((t) => t.Status === 'Passed').map((t) => t['Result Date'])),
      blocked: failed.length ? `Failed: ${failed.join(', ')}` : null,
      detail: complianceStatus !== 'Passed' && missing.length && !failed.length ? `Waiting on: ${missing.join(', ')}` : null },
    // Photo: done when all shots are delivered; note shows progress like "2/3 shots delivered".
    photo: { done: photoDone, completedOn: maxDate(shots.map((s) => s['Delivered Date'])),
      detail: !photoDone && shots.length ? `${shots.filter((s) => s.Status === 'Delivered').length}/${shots.length} shots delivered` : null },
    // ERP: done once the colorway has synced to ERPNext.
    erp: { done: colorway['Sync Status'] === 'Synced', completedOn: colorway['Last Synced At'] },
  };

  // Build the milestone list from the product model.
  const milestones = PRODUCT_MODEL.milestones
    // Skip "licensed only" milestones for prints that aren't licensed.
    .filter((m) => !m.licensedOnly || licensed)
    .map((m) => {
      // This milestone's state from above.
      const s = state[m.key];
      // Due date = launch date minus this milestone's lead time (null if no launch date).
      const due = launch ? addDaysIso(launch, -m.daysBeforeLaunch) : null;
      // Only a finished milestone has a completion date (e.g. the last *passed* test is not
      // "compliance passed" while other required tests are still pending).
      const completedOn = s.done && s.completedOn ? String(s.completedOn).slice(0, 10) : null;
      // Work out the status and how many days late.
      let status;
      let daysLate = 0;
      // Done: late if it finished after the due date.
      if (s.done) {
        daysLate = completedOn && due ? Math.max(0, daysBetween(due, completedOn)) : 0;
        status = daysLate > 0 ? 'done_late' : 'done_on_time';
      // Not done and no due date.
      } else if (!due) status = 'open_no_date';
      // Not done, with a due date.
      else {
        // Days until due (negative = already past).
        const daysUntil = daysBetween(today, due);
        if (daysUntil < 0) daysLate = -daysUntil;
        // Blocked beats everything; then late; then "at risk" if due soon; else on track.
        status = s.blocked ? 'blocked' : daysUntil < 0 ? 'open_late' : daysUntil <= PRODUCT_MODEL.atRiskWindowDays ? 'open_at_risk' : 'open_on_track';
      }
      // One row for this milestone.
      return { key: m.key, label: m.label, team: m.team, due, completedOn, status, daysLate, note: s.blocked || s.detail || null };
    });

  // Milestones not yet done.
  const open = milestones.filter((m) => !m.status.startsWith('done'));
  // Data issues (e.g. a malformed colorway number) will block the ERP sync later, so they
  // count as risk even when every date looks fine.
  // Overall timeline status, checked in this order.
  const timeline = !launch ? 'No Launch Date'
    : !open.length ? 'Complete'
    : open.some(isLate) ? 'Late'
    : open.some((m) => m.status === 'open_at_risk' || m.status === 'blocked') || issues.length ? 'At Risk'
    : 'On Track';
  // The next open milestone with the earliest due date (null if none).
  const next = open.filter((m) => m.due).sort((a, b) => a.due.localeCompare(b.due))[0] || null;

  // A symbol for each status, used in the text summary.
  const icon = { done_on_time: '✓', done_late: '✓', open_on_track: '○', open_at_risk: '!', open_late: '✗', blocked: '⛔', open_no_date: '○' };
  // The text summary, one line per data issue then one per milestone.
  const lines = [
    ...issues.map((i) => `⚠ Data: ${i}`),
    ...milestones.map((m) => {
      // Done: e.g. "✓ Sample: done 2026-09-01 (3 days late)".
      if (m.status.startsWith('done')) return `${icon[m.status]} ${m.label}: done ${m.completedOn || '(no date)'}${m.daysLate ? ` (${m.daysLate} days late)` : ''}`;
      // Not done: e.g. "✗ Photo: due 2026-10-01 (<team>), 11 days late · 2/3 shots delivered".
      const when = m.due ? `due ${m.due}` : 'no launch date';
      const lateness = m.status === 'open_late' || (m.status === 'blocked' && m.daysLate) ? `, ${m.daysLate} days late` : m.status === 'open_at_risk' ? ', at risk' : '';
      return `${icon[m.status]} ${m.label}: ${when} (${m.team})${lateness}${m.note ? ` · ${m.note}` : ''}`;
    }),
  ];

  return {
    issues,
    milestones,
    // The Airtable Colorway fields to write back.
    fields: {
      'SKU Base': skuBase || '',
      'Sample Status': sampleStatus,
      'Compliance Status': complianceStatus,
      'Photo Status': photoStatus,
      'Timeline Status': timeline,
      'Next Milestone': next ? `${next.label} (${next.team}), due ${next.due}` : '',
      'Next Due Date': next ? next.due : null,
      // The most days late of any open milestone (0 if none).
      'Days Late': Math.max(0, ...open.map((m) => m.daysLate)),
      'Critical Path': lines.join('\n'),
    },
  };
}

// Only send fields whose value changed: saves Airtable API calls and keeps the record's
// revision history meaningful. Airtable omits empty fields, so treat ''/null/undefined alike.
function diffFields(current, computed) {
  // Helper: treat undefined, null and '' all as null.
  const norm = (v) => (v === undefined || v === null || v === '' ? null : v);
  // The fields that differ.
  const changed = {};
  // Compare each computed field with what's in Airtable now.
  for (const [k, v] of Object.entries(computed)) {
    if (norm(current[k]) !== norm(v)) changed[k] = v;
  }
  // Return the changes, or null if nothing changed.
  return Object.keys(changed).length ? changed : null;
}

// One Slack message for the whole portfolio, grouped by owning team (alert per cause, not
// one ping per colorway). Returns null when nothing is late or at risk.
function buildTeamDigest(results, { maxPerTeam = 8 } = {}) {
  // team name → list of problem milestones.
  const byTeam = new Map();
  // Data problems across all colorways.
  const dataIssues = [];
  // Go through each colorway's results.
  for (const r of results) {
    for (const m of r.milestones) {
      // Only late, blocked or at-risk milestones go in the digest.
      if (!['open_late', 'blocked', 'open_at_risk'].includes(m.status)) continue;
      // First one for this team? Start its list.
      if (!byTeam.has(m.team)) byTeam.set(m.team, []);
      // Add the milestone, tagged with its colorway.
      byTeam.get(m.team).push({ ...m, colorway: r.colorwayName, skuBase: r.skuBase });
    }
    // Collect this colorway's data issues.
    for (const issue of r.issues || []) dataIssues.push(`  ⚠ ${r.colorwayName}: ${issue}`);
  }
  // Nothing to report? No message.
  if (!byTeam.size && !dataIssues.length) return null;
  // One section per team, teams in A–Z order.
  const sections = [...byTeam.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([team, items]) => {
    // Most days late first; ties broken by earliest due date.
    items.sort((a, b) => b.daysLate - a.daysLate || String(a.due).localeCompare(String(b.due)));
    // How many are actually late (the rest are at risk).
    const late = items.filter(isLate).length;
    // Section heading, e.g. "*<team>*: 2 late, 1 at risk".
    const head = `*${team}*: ${late} late, ${items.length - late} at risk`;
    // One line per milestone, up to maxPerTeam (8).
    const rows = items.slice(0, maxPerTeam).map((i) =>
      `  ${i.status === 'blocked' ? '⛔' : isLate(i) ? '✗' : '!'} ${i.colorway}${i.skuBase ? ` (${i.skuBase})` : ''}: ${i.label}, due ${i.due}${i.daysLate ? `, ${i.daysLate} days late` : ''}${i.note ? ` · ${i.note}` : ''}`);
    // Too many to list? Say how many were left out.
    if (items.length > maxPerTeam) rows.push(`  …and ${items.length - maxPerTeam} more`);
    return [head, ...rows].join('\n');
  });
  // Add a data issues section at the end, if there are any.
  if (dataIssues.length) sections.push([`*Data issues* (fix in Airtable): ${dataIssues.length}`, ...dataIssues.slice(0, maxPerTeam)].join('\n'));
  // Put it all together under one title.
  return [':calendar: *Launch critical path*: milestones late or due within a week', ...sections].join('\n');
}

// Split a list into smaller lists of "size" items each, e.g. chunk([1,2,3], 2) → [[1,2],[3]].
function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}
// ---- lib/shopify.js -----------------------------------------------------
// Shopify ↔ ERPNext helpers shared by the LS-04 / LS-05 Code nodes. Pure functions;
// the caller passes in `crypto` so this file runs in n8n and in unit tests alike.

// Shopify signs each webhook: base64(HMAC-SHA256(raw body, app client secret)) in the
// X-Shopify-Hmac-Sha256 header. Must be computed over the RAW bytes, never re-serialized JSON.
function verifyShopifyHmac(rawBody, secret, headerValue, cryptoLib) {
  // Missing the body, the secret or the signature? Can't be valid.
  if (!rawBody || !secret || !headerValue) return false;
  // Work out what the signature SHOULD be, using our copy of the secret.
  const expected = cryptoLib.createHmac('sha256', secret).update(rawBody).digest('base64');
  // Valid only if it matches the signature Shopify sent.
  return constantTimeEqual(expected, String(headerValue).trim());
}

// Compare without short-circuiting, so response timing doesn't leak how much matched.
function constantTimeEqual(a, b) {
  // Different lengths can never match.
  if (a.length !== b.length) return false;
  // Stays 0 only if every character matches.
  let diff = 0;
  // Compare every character (XOR is 0 when two characters are equal); never stop early.
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  // Equal if no differences were found.
  return diff === 0;
}

// Accepts BOTH shapes: the REST-style webhook payload (orders/create) and a GraphQL
// `orders` node from the safety-net poll. Uses the string GID, never the numeric `id`:
// Shopify IDs exceed Number.MAX_SAFE_INTEGER and get silently rounded by JSON.parse.
function normalizeShopifyOrder(o) {
  // Only the GraphQL shape has "lineItems", so that tells us which shape we have.
  const isGraphql = Boolean(o && o.lineItems);
  // The order lines, from whichever field this shape uses.
  const rawLines = isGraphql ? (o.lineItems.nodes || []) : (o.line_items || []);
  // Build one standard order shape, picking each value from the right field.
  const order = {
    orderGid: (isGraphql ? o.id : o.admin_graphql_api_id) || null,
    orderName: o.name || null,
    createdAt: (isGraphql ? o.createdAt : o.created_at) || null,
    currency: (isGraphql ? o.currencyCode : o.currency) || null,
    // true for Shopify test orders.
    test: Boolean(o.test),
    // Each line in a standard shape too.
    lines: rawLines.map((l) => ({
      // SKU with spaces trimmed off.
      sku: (l.sku || '').trim(),
      // Quantity as a number (0 if missing).
      qty: Number(l.quantity) || 0,
      // Unit price as a number; GraphQL keeps it deeper inside the line.
      price: Number(isGraphql ? l.originalUnitPriceSet && l.originalUnitPriceSet.shopMoney.amount : l.price),
      // A readable name for error messages.
      title: l.title || l.name || '',
    })),
  };

  // Reasons this order can't be imported (empty = fine).
  const holdReasons = [];
  // No order ID: we couldn't tell it apart from other orders.
  if (!order.orderGid) holdReasons.push('Order has no admin_graphql_api_id');
  // Nothing to import.
  if (!order.lines.length) holdReasons.push('Order has no line items');
  // Check each line.
  order.lines.forEach((l) => {
    // Every line needs a SKU to match it to an ERP item.
    if (!l.sku) holdReasons.push(`Line "${l.title}" has no SKU (gift card, custom item or a variant missing its SKU in Shopify)`);
    // Quantity must be more than zero.
    if (l.qty <= 0) holdReasons.push(`Line "${l.title}" has quantity ${l.qty}`);
    // Price must be a real number, 0 or more (this also catches "not a number").
    if (!(l.price >= 0)) holdReasons.push(`Line "${l.title}" has an unreadable price`);
  });
  // Return the order, plus its unique SKUs, whether it's valid, and any hold reasons.
  return { ...order, skus: [...new Set(order.lines.map((l) => l.sku).filter(Boolean))], valid: holdReasons.length === 0, holdReasons };
}

// Compare order SKUs with the ERP's Item list → reasons to hold the order (empty = OK).
function matchOrderSkus(order, erpItems) {
  // Lookup table: item code → ERP item.
  const byCode = new Map((erpItems || []).map((i) => [i.name, i]));
  // Problems found.
  const reasons = [];
  // Check each SKU on the order.
  for (const sku of order.skus) {
    // Find it in the ERP.
    const item = byCode.get(sku);
    // Not in the ERP at all.
    if (!item) reasons.push(`Unknown SKU ${sku}: no ERP item with this code`);
    // In the ERP but switched off.
    else if (Number(item.disabled)) reasons.push(`SKU ${sku} is disabled in the ERP`);
    // Templates (S-0108-0901) are style-level records; only size variants can be sold.
    else if (Number(item.has_variants)) reasons.push(`SKU ${sku} is a style template, not a size: the Shopify variant is missing its size code`);
  }
  return reasons;
}

// Add a number of days to a date like "2026-10-12" and return the new date in the same format.
function addDays(isoDate, days) {
  // Make a date at midnight UTC (so time zones can't shift the day).
  const d = new Date(`${isoDate.slice(0, 10)}T00:00:00Z`);
  // Move it forward by "days".
  d.setUTCDate(d.getUTCDate() + days);
  // Back to "YYYY-MM-DD".
  return d.toISOString().slice(0, 10);
}

// ERPNext Sales Order payload. One "channel customer" for all web orders: the common
// connector pattern when the ERP doesn't need individual consumers (and avoids PII).
function buildSalesOrder(order, { customer, company, warehouse, leadDays = 5 }) {
  // The order date (or today if missing), as "YYYY-MM-DD".
  const orderDate = (order.createdAt || new Date().toISOString()).slice(0, 10);
  // Expected delivery: order date plus 5 days by default.
  const deliveryDate = addDays(orderDate, leadDays);
  return {
    doctype: 'Sales Order',
    customer,
    // Only include company and warehouse if they were given.
    ...(company ? { company } : {}),
    ...(warehouse ? { set_warehouse: warehouse } : {}),
    transaction_date: orderDate,
    delivery_date: deliveryDate,
    // The Shopify order number (e.g. #1001) as the customer PO number.
    po_no: order.orderName,
    // Our custom fields that link this Sales Order back to the Shopify order.
    custom_shopify_order_id: order.orderGid,
    custom_shopify_order_name: order.orderName,
    // One Sales Order line per order line.
    items: order.lines.map((l) => ({
      item_code: l.sku,
      qty: l.qty,
      // Price rounded to 2 decimals (cents).
      rate: Math.round(l.price * 100) / 100,
      delivery_date: deliveryDate,
      ...(warehouse ? { warehouse } : {}),
    })),
    // Created as a draft, then submitted by a second call: in ERPNext v16 inserting with
    // docstatus=1 in one request skips the status update (doc stays 'Draft' while submitted).
  };
}

// GraphQL reports most failures with HTTP 200: check top-level `errors` (auth, throttling,
// bad query) AND the mutation's `userErrors` (validation). Missing either is a silent failure.
function graphqlOutcome(resp, mutationKey) {
  // Every problem found.
  const errors = [];
  // Top-level errors, e.g. "THROTTLED: too many requests".
  for (const e of (resp && resp.errors) || []) {
    errors.push(`${(e.extensions && e.extensions.code) || 'GRAPHQL'}: ${e.message}`);
  }
  // The part of the reply for our mutation (e.g. resp.data.productSet), or null.
  const payload = mutationKey && resp && resp.data ? resp.data[mutationKey] : null;
  // Validation errors on specific fields, e.g. "title: can't be blank".
  for (const u of (payload && payload.userErrors) || []) {
    errors.push(`${(u.field || []).join('.') || 'input'}: ${u.message}`);
  }
  // No errors but also no result? That's still a failure.
  if (mutationKey && !payload && !errors.length) errors.push(`No ${mutationKey} payload in response`);
  // ok = no errors. message = all errors in one line.
  return { ok: errors.length === 0, message: errors.join('; '), payload };
}

// ---- Safety-net poll (LS-05) ---------------------------------------------
// Two jobs, kept separate so neither depends on order volume:
//  1. Missed webhooks: page through ALL orders created in the last few hours, skipping
//     those the audit log already shows as imported.
//  2. Held / failed orders: fetch them BY ID from the audit log's list, so retries don't
//     depend on how many orders arrived since.
// Page sizes keep each query under Shopify's 1,000-point single-query cost limit
// (25 orders × 30 lines ≈ 775 requested points).
// The order fields we ask Shopify for (same list in both queries below).
const ORDER_FIELDS = 'id name createdAt currencyCode test lineItems(first: 30) { nodes { sku quantity title originalUnitPriceSet { shopMoney { amount } } } }';
// Query 1: recent orders, 25 per page. "$after" says which page to fetch next.
const RECENT_ORDERS_QUERY = `query recentOrders($q: String!, $after: String) { orders(first: 25, after: $after, query: $q, sortKey: CREATED_AT) { pageInfo { hasNextPage endCursor } nodes { ${ORDER_FIELDS} } } }`;
// Query 2: specific orders by their IDs.
const ORDERS_BY_ID_QUERY = `query ordersById($ids: [ID!]!) { nodes(ids: $ids) { ... on Order { ${ORDER_FIELDS} } } }`;

// Audit rows (latest attempt per Shopify order) → what the poll should skip and retry.
function classifySyncState(rows) {
  // Orders already done (no need to fetch again).
  const imported = new Set();
  // Orders that failed and should be tried again.
  const retry = [];
  // Look at each audit row.
  for (const r of rows || []) {
    // Skip empty rows (e.g. the placeholder row when there's no history yet).
    if (!r || !r.order_gid) continue;
    // Imported, or skipped as a duplicate: done.
    if (r.status === 'success' || r.status === 'skipped') imported.add(r.order_gid);
    // Failed to import: retry it.
    else if (r.status === 'failed' && r.action === 'import_order') retry.push(r.order_gid);
    // verify_signature failures are NOT retried by ID (the GID may be forged); if it was a
    // real order rejected after a secret rotation, the recent-orders pass picks it up.
  }
  return { imported, retry };
}

// graphql(query, variables) → response body; sleep(ms) → Promise. Both injected so this runs
// in an n8n Code node (this.helpers.httpRequest) and in unit tests (mocks).
async function fetchOrdersToReconcile({ graphql, sinceIso, imported, retryGids, maxPages = 200, sleep = async () => {} }) {
  // Counters for the execution log.
  const stats = { pages: 0, scanned: 0, skippedImported: 0, retriedById: 0, truncated: false, throttleWaits: 0 };
  // Orders to process, keyed by ID so none appears twice.
  const byId = new Map();

  // Helper: run a query; if Shopify says "slow down" (THROTTLED), wait and try again.
  const call = async (query, variables) => {
    // Up to 6 tries.
    for (let attempt = 0; attempt < 6; attempt++) {
      // Send the query and wait for the reply.
      const resp = await graphql(query, variables);
      // Did Shopify say we're going too fast?
      const throttled = (resp.errors || []).some((e) => e.extensions && e.extensions.code === 'THROTTLED');
      // Not throttled:
      if (!throttled) {
        // Any other error is a real failure: stop with an error.
        if (resp.errors && resp.errors.length) throw new Error(`Shopify GraphQL: ${resp.errors.map((e) => e.message).join('; ')}`);
        // Success: return the data.
        return resp.data;
      }
      // Throttled: count it...
      stats.throttleWaits++;
      // ...and wait a bit longer each time (2s, 4s, 6s…) before trying again.
      await sleep(2000 * (attempt + 1)); // cost bucket refills each second; back off and retry
    }
    // Still throttled after 6 tries: give up with an error.
    throw new Error('Shopify GraphQL: still THROTTLED after 6 attempts');
  };

  // Job 1: page through recent orders. "after" marks where the next page starts (null = first page).
  let after = null;
  do {
    // Safety limit: stop after too many pages and note that the list was cut short.
    if (stats.pages >= maxPages) { stats.truncated = true; break; }
    // Fetch one page of orders created since "sinceIso".
    const data = await call(RECENT_ORDERS_QUERY, { q: `created_at:>='${sinceIso}'`, after });
    stats.pages++;
    // Check each order on the page.
    for (const o of data.orders.nodes) {
      stats.scanned++;
      // Already imported? Skip it. Otherwise add it to the list to process.
      if (imported.has(o.id)) stats.skippedImported++;
      else byId.set(o.id, o);
    }
    // More pages? Remember where the next one starts. Otherwise null, which ends the loop.
    after = data.orders.pageInfo.hasNextPage ? data.orders.pageInfo.endCursor : null;
  } while (after);

  // Job 2: orders to retry that weren't already picked up in Job 1 (duplicates removed).
  const pending = [...new Set(retryGids)].filter((id) => !byId.has(id));
  // Fetch them 25 at a time.
  for (let i = 0; i < pending.length; i += 25) {
    const data = await call(ORDERS_BY_ID_QUERY, { ids: pending.slice(i, i + 25) });
    // Add each order Shopify returned.
    for (const o of data.nodes || []) {
      if (o && o.id) { byId.set(o.id, o); stats.retriedById++; } // null = order deleted in Shopify
    }
  }
  // Return the orders as a list, plus the counters.
  return { orders: [...byId.values()], stats };
}

// The Shopify request that creates (or updates) a product with all its variants in one go.
const PRODUCT_SET_MUTATION =`mutation productSet($input: ProductSetInput!) {
  productSet(synchronous: true, input: $input) {
    product { id status variants(first: 1) { nodes { id sku } } }
    userErrors { field message }
  }
}`;

// Tag taxonomy modelled on the live storefront (division:, print_family:, launchMMDDYY…).
// Make text tag-safe: lowercase, non-letters/digits become "-", no "-" at either end.
const tagSlug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
// Turn "2026-10-12" into "101226" (month, day, 2-digit year). null if no date.
const mmddyy = (iso) => (iso ? `${iso.slice(5, 7)}${iso.slice(8, 10)}${iso.slice(2, 4)}` : null);

// Build the list of Shopify tags for a product.
function shopifyTags(item, price) {
  // Each line is a tag, or false/null when the data for it is missing ("a && b" gives b only if a is set).
  const tags = [
    `division:${tagSlug(item.item_group)}`,
    item.custom_print_family && `print_family:${item.custom_print_family}`,
    item.custom_print_category && `print_category:${tagSlug(item.custom_print_category)}`,
    item.custom_launch_date && `launch${mmddyy(item.custom_launch_date)}`,
    item.custom_merch_date && `merch${mmddyy(item.custom_merch_date)}`,
    item.custom_inventory_tier && `inventory_tier:${item.custom_inventory_tier}`,
    Number(item.custom_limited_edition) && 'tag_Limited Edition',
    // Always added, so we can find products this sync created.
    'erp-sync',
    // Flag products with no price yet.
    price === '0.00' && 'needs-pricing',
  ];
  // Drop the false/null entries.
  return tags.filter(Boolean);
}

// ERPNext style TEMPLATE → Shopify productSet: one DRAFT product per colorway with a Size
// option and one variant per size (SKU = template code + size code, same rule ERPNext uses
// for its variants). Built from the template's size run, so it doesn't race the ERP's
// variant creation. Draft, because merchandising owns imagery and publishing.
// Needs lib/product-model.js (sizeRunSkus).
function buildProductSetRequest(item) {
  // Retail price as text with 2 decimals, or "0.00" if there isn't a positive price.
  const price = Number(item.custom_retail_price) > 0 ? Number(item.custom_retail_price).toFixed(2) : '0.00';
  // Turn the stored size run ("Preemie|Newborn|…") into one SKU per size. "unknown" = sizes with no code.
  const { variants, unknown } = sizeRunSkus(item.name, String(item.custom_size_run || '').split('|').filter(Boolean));
  // No usable sizes? Stop with a clear error.
  if (!variants.length) throw new Error(`Template ${item.name} has no size run with known size codes (${unknown.join(', ') || 'empty'})`);
  return {
    query: PRODUCT_SET_MUTATION,
    variables: {
      input: {
        title: item.item_name,
        // Always a draft: a person publishes it later.
        status: 'DRAFT',
        vendor: 'LSS Demo', // not the real brand: this is an unaffiliated demo store
        productType: item.custom_product_type || item.item_group,
        // The description in a paragraph, with "<" and ">" removed so it can't inject HTML.
        descriptionHtml: `<p>${String(item.description || '').replace(/[<>]/g, '')}</p>`,
        tags: shopifyTags(item, price),
        // One "Size" option listing every size.
        productOptions: [{ name: 'Size', position: 1, values: variants.map((v) => ({ name: v.size })) }],
        // One variant per size, each with its own SKU and the same price.
        variants: variants.map((v) => ({ optionValues: [{ optionName: 'Size', name: v.size }], price, sku: v.sku })),
      },
    },
    // The first size's SKU, used to check if the product already exists in Shopify.
    firstSku: variants[0].sku,
  };
}
// The ERP item can arrive wrapped in "data" or on its own; handle both.
const item = $json.data || $json;
// Build the Shopify "create product" request. Pull "firstSku" out separately and keep
// everything else in productSetBody.
const { firstSku, ...productSetBody } = buildProductSetRequest(item);
// Send one item on to the next node.
return { json: {
  // The ERP item code (the style template's SKU base).
  sku: item.name,
  // The human-readable product name.
  itemName: item.item_name,
  // How many sizes (variants) the product will have.
  variantCount: productSetBody.variables.input.variants.length,
  // A Shopify query that checks "does a variant with this SKU already exist?"
  // so we never create the same product twice.
  findVariantBody: {
    query: 'query findVariant($q: String!) { productVariants(first: 1, query: $q) { nodes { id sku product { id status } } } }',
    // JSON.stringify wraps the SKU in quotes so Shopify searches for it exactly.
    variables: { q: `sku:${JSON.stringify(firstSku)}` },
  },
  // The full "create product" request, used only if the lookup finds nothing.
  productSetBody,
} };

// Mode: Run Once for Each Item
// HTTP 200 doesn't mean success in GraphQL: inspect `errors` and `userErrors`.
// ---- lib/sync-helpers.js ------------------------------------------------
// Error parsing, audit rows, Airtable write-backs and PO explosion shared by
// the n8n Code nodes. Pure functions only — no n8n globals in here.

// Frappe/ERPNext maps exceptions to HTTP codes; knowing them speeds up triage.
// Lookup table: HTTP status code → a short, readable error category.
const ERP_ERROR_CATEGORIES = {
  401: 'auth',            // AuthenticationError — bad/expired API key:secret
  403: 'permission',      // PermissionError — role lacks perm on the DocType
  404: 'not_found',       // DoesNotExistError
  409: 'duplicate',       // DuplicateEntryError — item_code already exists
  417: 'validation',      // ValidationError / LinkValidationError / MandatoryError
  429: 'rate_limited',
};

// Pulls a JSON object out of an error string. n8n 2.x formats HTTP errors as
//   417 - "{\"exc_type\":\"LinkValidationError\",...}"
// i.e. the response body as a JSON *string literal*, so it may need two parses.
function extractJsonBody(part) {
  // Already an object? Nothing to do, return it.
  if (part && typeof part === 'object') return part;
  // Make it text, strip a leading "417 - " style status code, and trim spaces.
  const s = String(part || '').replace(/^\s*\d{3} - /, '').trim();
  // Two things to try: the whole text, and just the part from the first "{" to the last "}".
  const attempts = [s, s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1)];
  // Try each one in turn.
  for (const candidate of attempts) {
    try {
      // Read the text as JSON.
      let v = JSON.parse(candidate);
      // If that gave us more text (JSON inside a string), read it as JSON again.
      if (typeof v === 'string') v = JSON.parse(v);
      // Got a real object? Return it.
      if (v && typeof v === 'object') return v;
    } catch { /* try the next shape */ }
  }
  // Nothing worked: no JSON found.
  return null;
}

// Normalizes an n8n error-output item ({ error: {...} }) from an HTTP Request node.
// Shape verified against n8n 2.39.6 (see tests); kept defensive for other versions.
function summarizeHttpError(itemJson) {
  // The error details: inside "error" if present, else the item itself, else an empty object.
  const e = (itemJson && itemJson.error) || itemJson || {};
  // Gather every bit of error text we can find into one string, separated by " | ".
  const text = [e.message, typeof e.description === 'string' ? e.description : '', typeof e === 'string' ? e : '']
    // Drop the empty bits.
    .filter(Boolean)
    // Make sure each bit is text.
    .map(String)
    // Join them.
    .join(' | ');

  // Look for the HTTP status code in the usual fields (null if none found).
  let httpStatus = Number(e.httpCode || e.statusCode || e.status) || null;
  // Not found? Try to read it from the error text instead.
  if (!httpStatus) {
    // Only trust the shapes n8n/axios actually emit ("409 - ...", "status code 502"),
    // so digits inside IPs or ports (ECONNREFUSED 172.18.0.5:8080) aren't misread.
    const m = text.match(/^([1-5]\d{2}) - /) || text.match(/status code ([1-5]\d{2})\b/i);
    // Found a match? Use the 3-digit number. Otherwise still null.
    httpStatus = m ? Number(m[1]) : null;
  }

  // Pull exc_type / _server_messages (ERPNext) or error.message (Airtable) out of the body.
  // The error type name, e.g. "LinkValidationError".
  let excType = null;
  // The human-readable message from the server.
  let serverMessage = null;
  // Look for a JSON body in the message, or failing that in the description.
  const body = extractJsonBody(e.message) || extractJsonBody(e.description);
  // Only dig further if we found one.
  if (body) {
    // ERPNext puts the type in exc_type; Airtable puts it in error.type.
    excType = body.exc_type || (body.error && body.error.type) || null;
    // ERPNext style 1: a list of messages, itself stored as JSON text.
    if (body._server_messages) {
      try {
        // Read the list, then read each message (also JSON) and keep its "message" part.
        serverMessage = JSON.parse(body._server_messages)
          .map((m) => { try { return JSON.parse(m).message; } catch { return m; } })
          // Join them with "; ".
          .join('; ');
      } catch { /* malformed — ignore */ }
    // ERPNext style 2: a Python traceback. The last line holds the actual error.
    } else if (body.exception) {
      serverMessage = String(body.exception).split('\n').pop();
    // Airtable style: error.message.
    } else if (body.error && body.error.message) {
      serverMessage = body.error.message;
    }
    // Remove any HTML tags (like <b>) from the message.
    if (serverMessage) serverMessage = serverMessage.replace(/<[^>]+>/g, '');
  }

  // Pick a category: from the table above, else "server" for 5xx codes,
  // "client" for other codes, or "network" if there was no code at all.
  const category = ERP_ERROR_CATEGORIES[httpStatus] || (httpStatus >= 500 ? 'server' : httpStatus ? 'client' : 'network');
  // These kinds of error usually fix themselves, so it's worth trying again later.
  const retryable = category === 'server' || category === 'rate_limited' || category === 'network';
  // Plain-text bodies arrive JSON-quoted (sometimes twice): 502 - "\"Bad Gateway\"".
  // Backup message: the raw error text without the leading status code.
  let fallback = String(e.message || text || 'Unknown error').replace(/^\s*\d{3} - /, '');
  // Remove up to two layers of JSON quotes.
  for (let i = 0; i < 2; i++) {
    try {
      // Read it as JSON.
      const v = JSON.parse(fallback);
      // Not plain text underneath? Stop and keep what we have.
      if (typeof v !== 'string') break;
      // Keep the unquoted text.
      fallback = v;
    } catch { break; }
  }
  // Final message, e.g. "HTTP 417 — LinkValidationError — Item Group X not found".
  const message = [httpStatus && `HTTP ${httpStatus}`, excType, serverMessage || fallback]
    // Drop empty parts.
    .filter(Boolean)
    // Join with " — ".
    .join(' — ')
    // Cut to 1000 characters.
    .slice(0, 1000);

  // Hand back the summary.
  return { httpStatus, category, retryable, excType, message };
}

// One row for audit.sync_audit_logs. Column order matches the INSERT in the Postgres nodes.
// Takes friendly names (f.entityId) and returns database column names (entity_id).
// "|| null" means: use null when the value is missing.
function auditRow(f) {
  return {
    // The n8n run ID as text.
    execution_id: f.executionId != null ? String(f.executionId) : null,
    workflow_name: f.workflowName || null,
    // Where the data came from and where it was going.
    source_system: f.source,
    target_system: f.target,
    // What kind of thing (e.g. sales_order) and which one.
    entity_type: f.entityType,
    entity_id: f.entityId || null,
    sku: f.sku || null,
    // What we tried and how it went.
    action: f.action,
    status: f.status,
    // "??" keeps 0 but turns missing into null.
    http_status: f.httpStatus ?? null,
    // Error text cut to 1000 characters, or null if there was no error.
    error_message: f.errorMessage ? String(f.errorMessage).slice(0, 1000) : null,
    approved_at: f.approvedAt || null,
    // Extra details (empty object if none).
    payload: f.payload || {},
  };
}

// PATCH body for writing sync results back onto the Airtable Colorways record.
// Transient failures go back to "Pending" so the safety-net poll retries them;
// permanent ones go to "Error" for a human. (n8n ignores Retry On Fail on nodes that
// use an error output, so this is the retry mechanism for ERP calls. See RUNBOOK §3.)
function syncWriteback({ status, erpItemCode, errorMessage, nowIso, retryable = false }) {
  // Did the sync work?
  const ok = status === 'success';
  return {
    fields: {
      // Worked → "Synced". Temporary failure → "Pending" (retry). Permanent failure → "Error".
      'Sync Status': ok ? 'Synced' : retryable ? 'Pending' : 'Error',
      // Only on success: also save the ERP item code.
      ...(ok && erpItemCode ? { 'ERP Item Code': erpItemCode } : {}),
      // Clear the error on success; otherwise save it (cut to 5000 characters).
      'Last Sync Error': ok ? '' : String(errorMessage || '').slice(0, 5000),
      // When this happened.
      'Last Synced At': nowIso,
    },
    // Let Airtable convert values to the right field type.
    typecast: true,
  };
}

// Airtable formula: {Field}='value' with quotes/backslashes escaped.
function airtableEquals(field, value) {
  // Make the value text, then put a "\" before any "\" or "'" so they can't break the formula.
  const escaped = String(value ?? '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  // Build the formula, e.g. {ERP Item Code}='S-0108-0901'.
  return `{${field}}='${escaped}'`;
}

// ERPNext Purchase Order doc → one row per COLORWAY (POs are placed per size variant,
// S-0108-0901-10, but Production tracks the colorway S-0108-0901): summed qty, earliest
// schedule date and a per-size breakdown. Needs lib/product-model.js for parseSku.
function explodePurchaseOrder(po) {
  // Running totals: colorway SKU → { qty, date, sizes }.
  const byColorway = new Map();
  // Go through each line on the PO.
  for (const line of po.items || []) {
    // Split the SKU into its parts (division, style, colorway, size).
    const parsed = parseSku(line.item_code);
    // The colorway SKU (without the size), or the raw code if it couldn't be parsed.
    const base = parsed ? `${parsed.divisionCode}-${parsed.style}-${parsed.colorway}` : line.item_code;
    // The size label (e.g. "Preemie"), or null if the SKU has no size.
    const size = parsed && parsed.sizeCode ? sizeLabelFor(parsed.divisionCode, parsed.sizeCode) : null;
    // Quantity as a number (0 if missing).
    const qty = Number(line.qty) || 0;
    // Delivery date: the line's own date, else the PO's date, else none.
    const date = line.schedule_date || po.schedule_date || null;
    // First line for this colorway? Start its running totals at zero.
    if (!byColorway.has(base)) byColorway.set(base, { qty: 0, date: null, sizes: [] });
    // Get the running totals for this colorway.
    const agg = byColorway.get(base);
    // Add this line's quantity.
    agg.qty += qty;
    // Keep the earliest date seen.
    if (date && (!agg.date || date < agg.date)) agg.date = date;
    // Note the size and quantity, e.g. "Preemie ×12".
    if (size) agg.sizes.push(`${size} ×${qty}`);
  }
  // Turn the totals into one output row per colorway.
  return [...byColorway.entries()].map(([base, agg]) => ({
    po_number: po.name,
    supplier: po.supplier,
    // The PO status, or work it out: docstatus 1 means submitted, otherwise draft.
    po_status: po.status || (po.docstatus === 1 ? 'Submitted' : 'Draft'),
    item_code: base,
    qty: agg.qty,
    expected_delivery: agg.date,
    // Formula used to find the matching Airtable record.
    airtable_formula: airtableEquals('ERP Item Code', base),
    // The fields to write onto that Airtable record.
    airtable_fields: {
      'PO Number': po.name,
      'PO Qty': agg.qty,
      // e.g. "Preemie ×12, Newborn ×24" (null if no sizes).
      'PO Size Breakdown': agg.sizes.join(', ') || null,
      Vendor: po.supplier,
      'Expected Delivery': agg.date,
      'PO Status': po.status || null,
    },
  }));
}
// ---- lib/shopify.js -----------------------------------------------------
// Shopify ↔ ERPNext helpers shared by the LS-04 / LS-05 Code nodes. Pure functions;
// the caller passes in `crypto` so this file runs in n8n and in unit tests alike.

// Shopify signs each webhook: base64(HMAC-SHA256(raw body, app client secret)) in the
// X-Shopify-Hmac-Sha256 header. Must be computed over the RAW bytes, never re-serialized JSON.
function verifyShopifyHmac(rawBody, secret, headerValue, cryptoLib) {
  // Missing the body, the secret or the signature? Can't be valid.
  if (!rawBody || !secret || !headerValue) return false;
  // Work out what the signature SHOULD be, using our copy of the secret.
  const expected = cryptoLib.createHmac('sha256', secret).update(rawBody).digest('base64');
  // Valid only if it matches the signature Shopify sent.
  return constantTimeEqual(expected, String(headerValue).trim());
}

// Compare without short-circuiting, so response timing doesn't leak how much matched.
function constantTimeEqual(a, b) {
  // Different lengths can never match.
  if (a.length !== b.length) return false;
  // Stays 0 only if every character matches.
  let diff = 0;
  // Compare every character (XOR is 0 when two characters are equal); never stop early.
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  // Equal if no differences were found.
  return diff === 0;
}

// Accepts BOTH shapes: the REST-style webhook payload (orders/create) and a GraphQL
// `orders` node from the safety-net poll. Uses the string GID, never the numeric `id`:
// Shopify IDs exceed Number.MAX_SAFE_INTEGER and get silently rounded by JSON.parse.
function normalizeShopifyOrder(o) {
  // Only the GraphQL shape has "lineItems", so that tells us which shape we have.
  const isGraphql = Boolean(o && o.lineItems);
  // The order lines, from whichever field this shape uses.
  const rawLines = isGraphql ? (o.lineItems.nodes || []) : (o.line_items || []);
  // Build one standard order shape, picking each value from the right field.
  const order = {
    orderGid: (isGraphql ? o.id : o.admin_graphql_api_id) || null,
    orderName: o.name || null,
    createdAt: (isGraphql ? o.createdAt : o.created_at) || null,
    currency: (isGraphql ? o.currencyCode : o.currency) || null,
    // true for Shopify test orders.
    test: Boolean(o.test),
    // Each line in a standard shape too.
    lines: rawLines.map((l) => ({
      // SKU with spaces trimmed off.
      sku: (l.sku || '').trim(),
      // Quantity as a number (0 if missing).
      qty: Number(l.quantity) || 0,
      // Unit price as a number; GraphQL keeps it deeper inside the line.
      price: Number(isGraphql ? l.originalUnitPriceSet && l.originalUnitPriceSet.shopMoney.amount : l.price),
      // A readable name for error messages.
      title: l.title || l.name || '',
    })),
  };

  // Reasons this order can't be imported (empty = fine).
  const holdReasons = [];
  // No order ID: we couldn't tell it apart from other orders.
  if (!order.orderGid) holdReasons.push('Order has no admin_graphql_api_id');
  // Nothing to import.
  if (!order.lines.length) holdReasons.push('Order has no line items');
  // Check each line.
  order.lines.forEach((l) => {
    // Every line needs a SKU to match it to an ERP item.
    if (!l.sku) holdReasons.push(`Line "${l.title}" has no SKU (gift card, custom item or a variant missing its SKU in Shopify)`);
    // Quantity must be more than zero.
    if (l.qty <= 0) holdReasons.push(`Line "${l.title}" has quantity ${l.qty}`);
    // Price must be a real number, 0 or more (this also catches "not a number").
    if (!(l.price >= 0)) holdReasons.push(`Line "${l.title}" has an unreadable price`);
  });
  // Return the order, plus its unique SKUs, whether it's valid, and any hold reasons.
  return { ...order, skus: [...new Set(order.lines.map((l) => l.sku).filter(Boolean))], valid: holdReasons.length === 0, holdReasons };
}

// Compare order SKUs with the ERP's Item list → reasons to hold the order (empty = OK).
function matchOrderSkus(order, erpItems) {
  // Lookup table: item code → ERP item.
  const byCode = new Map((erpItems || []).map((i) => [i.name, i]));
  // Problems found.
  const reasons = [];
  // Check each SKU on the order.
  for (const sku of order.skus) {
    // Find it in the ERP.
    const item = byCode.get(sku);
    // Not in the ERP at all.
    if (!item) reasons.push(`Unknown SKU ${sku}: no ERP item with this code`);
    // In the ERP but switched off.
    else if (Number(item.disabled)) reasons.push(`SKU ${sku} is disabled in the ERP`);
    // Templates (S-0108-0901) are style-level records; only size variants can be sold.
    else if (Number(item.has_variants)) reasons.push(`SKU ${sku} is a style template, not a size: the Shopify variant is missing its size code`);
  }
  return reasons;
}

// Add a number of days to a date like "2026-10-12" and return the new date in the same format.
function addDays(isoDate, days) {
  // Make a date at midnight UTC (so time zones can't shift the day).
  const d = new Date(`${isoDate.slice(0, 10)}T00:00:00Z`);
  // Move it forward by "days".
  d.setUTCDate(d.getUTCDate() + days);
  // Back to "YYYY-MM-DD".
  return d.toISOString().slice(0, 10);
}

// ERPNext Sales Order payload. One "channel customer" for all web orders: the common
// connector pattern when the ERP doesn't need individual consumers (and avoids PII).
function buildSalesOrder(order, { customer, company, warehouse, leadDays = 5 }) {
  // The order date (or today if missing), as "YYYY-MM-DD".
  const orderDate = (order.createdAt || new Date().toISOString()).slice(0, 10);
  // Expected delivery: order date plus 5 days by default.
  const deliveryDate = addDays(orderDate, leadDays);
  return {
    doctype: 'Sales Order',
    customer,
    // Only include company and warehouse if they were given.
    ...(company ? { company } : {}),
    ...(warehouse ? { set_warehouse: warehouse } : {}),
    transaction_date: orderDate,
    delivery_date: deliveryDate,
    // The Shopify order number (e.g. #1001) as the customer PO number.
    po_no: order.orderName,
    // Our custom fields that link this Sales Order back to the Shopify order.
    custom_shopify_order_id: order.orderGid,
    custom_shopify_order_name: order.orderName,
    // One Sales Order line per order line.
    items: order.lines.map((l) => ({
      item_code: l.sku,
      qty: l.qty,
      // Price rounded to 2 decimals (cents).
      rate: Math.round(l.price * 100) / 100,
      delivery_date: deliveryDate,
      ...(warehouse ? { warehouse } : {}),
    })),
    // Created as a draft, then submitted by a second call: in ERPNext v16 inserting with
    // docstatus=1 in one request skips the status update (doc stays 'Draft' while submitted).
  };
}

// GraphQL reports most failures with HTTP 200: check top-level `errors` (auth, throttling,
// bad query) AND the mutation's `userErrors` (validation). Missing either is a silent failure.
function graphqlOutcome(resp, mutationKey) {
  // Every problem found.
  const errors = [];
  // Top-level errors, e.g. "THROTTLED: too many requests".
  for (const e of (resp && resp.errors) || []) {
    errors.push(`${(e.extensions && e.extensions.code) || 'GRAPHQL'}: ${e.message}`);
  }
  // The part of the reply for our mutation (e.g. resp.data.productSet), or null.
  const payload = mutationKey && resp && resp.data ? resp.data[mutationKey] : null;
  // Validation errors on specific fields, e.g. "title: can't be blank".
  for (const u of (payload && payload.userErrors) || []) {
    errors.push(`${(u.field || []).join('.') || 'input'}: ${u.message}`);
  }
  // No errors but also no result? That's still a failure.
  if (mutationKey && !payload && !errors.length) errors.push(`No ${mutationKey} payload in response`);
  // ok = no errors. message = all errors in one line.
  return { ok: errors.length === 0, message: errors.join('; '), payload };
}

// ---- Safety-net poll (LS-05) ---------------------------------------------
// Two jobs, kept separate so neither depends on order volume:
//  1. Missed webhooks: page through ALL orders created in the last few hours, skipping
//     those the audit log already shows as imported.
//  2. Held / failed orders: fetch them BY ID from the audit log's list, so retries don't
//     depend on how many orders arrived since.
// Page sizes keep each query under Shopify's 1,000-point single-query cost limit
// (25 orders × 30 lines ≈ 775 requested points).
// The order fields we ask Shopify for (same list in both queries below).
const ORDER_FIELDS = 'id name createdAt currencyCode test lineItems(first: 30) { nodes { sku quantity title originalUnitPriceSet { shopMoney { amount } } } }';
// Query 1: recent orders, 25 per page. "$after" says which page to fetch next.
const RECENT_ORDERS_QUERY = `query recentOrders($q: String!, $after: String) { orders(first: 25, after: $after, query: $q, sortKey: CREATED_AT) { pageInfo { hasNextPage endCursor } nodes { ${ORDER_FIELDS} } } }`;
// Query 2: specific orders by their IDs.
const ORDERS_BY_ID_QUERY = `query ordersById($ids: [ID!]!) { nodes(ids: $ids) { ... on Order { ${ORDER_FIELDS} } } }`;

// Audit rows (latest attempt per Shopify order) → what the poll should skip and retry.
function classifySyncState(rows) {
  // Orders already done (no need to fetch again).
  const imported = new Set();
  // Orders that failed and should be tried again.
  const retry = [];
  // Look at each audit row.
  for (const r of rows || []) {
    // Skip empty rows (e.g. the placeholder row when there's no history yet).
    if (!r || !r.order_gid) continue;
    // Imported, or skipped as a duplicate: done.
    if (r.status === 'success' || r.status === 'skipped') imported.add(r.order_gid);
    // Failed to import: retry it.
    else if (r.status === 'failed' && r.action === 'import_order') retry.push(r.order_gid);
    // verify_signature failures are NOT retried by ID (the GID may be forged); if it was a
    // real order rejected after a secret rotation, the recent-orders pass picks it up.
  }
  return { imported, retry };
}

// graphql(query, variables) → response body; sleep(ms) → Promise. Both injected so this runs
// in an n8n Code node (this.helpers.httpRequest) and in unit tests (mocks).
async function fetchOrdersToReconcile({ graphql, sinceIso, imported, retryGids, maxPages = 200, sleep = async () => {} }) {
  // Counters for the execution log.
  const stats = { pages: 0, scanned: 0, skippedImported: 0, retriedById: 0, truncated: false, throttleWaits: 0 };
  // Orders to process, keyed by ID so none appears twice.
  const byId = new Map();

  // Helper: run a query; if Shopify says "slow down" (THROTTLED), wait and try again.
  const call = async (query, variables) => {
    // Up to 6 tries.
    for (let attempt = 0; attempt < 6; attempt++) {
      // Send the query and wait for the reply.
      const resp = await graphql(query, variables);
      // Did Shopify say we're going too fast?
      const throttled = (resp.errors || []).some((e) => e.extensions && e.extensions.code === 'THROTTLED');
      // Not throttled:
      if (!throttled) {
        // Any other error is a real failure: stop with an error.
        if (resp.errors && resp.errors.length) throw new Error(`Shopify GraphQL: ${resp.errors.map((e) => e.message).join('; ')}`);
        // Success: return the data.
        return resp.data;
      }
      // Throttled: count it...
      stats.throttleWaits++;
      // ...and wait a bit longer each time (2s, 4s, 6s…) before trying again.
      await sleep(2000 * (attempt + 1)); // cost bucket refills each second; back off and retry
    }
    // Still throttled after 6 tries: give up with an error.
    throw new Error('Shopify GraphQL: still THROTTLED after 6 attempts');
  };

  // Job 1: page through recent orders. "after" marks where the next page starts (null = first page).
  let after = null;
  do {
    // Safety limit: stop after too many pages and note that the list was cut short.
    if (stats.pages >= maxPages) { stats.truncated = true; break; }
    // Fetch one page of orders created since "sinceIso".
    const data = await call(RECENT_ORDERS_QUERY, { q: `created_at:>='${sinceIso}'`, after });
    stats.pages++;
    // Check each order on the page.
    for (const o of data.orders.nodes) {
      stats.scanned++;
      // Already imported? Skip it. Otherwise add it to the list to process.
      if (imported.has(o.id)) stats.skippedImported++;
      else byId.set(o.id, o);
    }
    // More pages? Remember where the next one starts. Otherwise null, which ends the loop.
    after = data.orders.pageInfo.hasNextPage ? data.orders.pageInfo.endCursor : null;
  } while (after);

  // Job 2: orders to retry that weren't already picked up in Job 1 (duplicates removed).
  const pending = [...new Set(retryGids)].filter((id) => !byId.has(id));
  // Fetch them 25 at a time.
  for (let i = 0; i < pending.length; i += 25) {
    const data = await call(ORDERS_BY_ID_QUERY, { ids: pending.slice(i, i + 25) });
    // Add each order Shopify returned.
    for (const o of data.nodes || []) {
      if (o && o.id) { byId.set(o.id, o); stats.retriedById++; } // null = order deleted in Shopify
    }
  }
  // Return the orders as a list, plus the counters.
  return { orders: [...byId.values()], stats };
}

// The Shopify request that creates (or updates) a product with all its variants in one go.
const PRODUCT_SET_MUTATION =`mutation productSet($input: ProductSetInput!) {
  productSet(synchronous: true, input: $input) {
    product { id status variants(first: 1) { nodes { id sku } } }
    userErrors { field message }
  }
}`;

// Tag taxonomy modelled on the live storefront (division:, print_family:, launchMMDDYY…).
// Make text tag-safe: lowercase, non-letters/digits become "-", no "-" at either end.
const tagSlug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
// Turn "2026-10-12" into "101226" (month, day, 2-digit year). null if no date.
const mmddyy = (iso) => (iso ? `${iso.slice(5, 7)}${iso.slice(8, 10)}${iso.slice(2, 4)}` : null);

// Build the list of Shopify tags for a product.
function shopifyTags(item, price) {
  // Each line is a tag, or false/null when the data for it is missing ("a && b" gives b only if a is set).
  const tags = [
    `division:${tagSlug(item.item_group)}`,
    item.custom_print_family && `print_family:${item.custom_print_family}`,
    item.custom_print_category && `print_category:${tagSlug(item.custom_print_category)}`,
    item.custom_launch_date && `launch${mmddyy(item.custom_launch_date)}`,
    item.custom_merch_date && `merch${mmddyy(item.custom_merch_date)}`,
    item.custom_inventory_tier && `inventory_tier:${item.custom_inventory_tier}`,
    Number(item.custom_limited_edition) && 'tag_Limited Edition',
    // Always added, so we can find products this sync created.
    'erp-sync',
    // Flag products with no price yet.
    price === '0.00' && 'needs-pricing',
  ];
  // Drop the false/null entries.
  return tags.filter(Boolean);
}

// ERPNext style TEMPLATE → Shopify productSet: one DRAFT product per colorway with a Size
// option and one variant per size (SKU = template code + size code, same rule ERPNext uses
// for its variants). Built from the template's size run, so it doesn't race the ERP's
// variant creation. Draft, because merchandising owns imagery and publishing.
// Needs lib/product-model.js (sizeRunSkus).
function buildProductSetRequest(item) {
  // Retail price as text with 2 decimals, or "0.00" if there isn't a positive price.
  const price = Number(item.custom_retail_price) > 0 ? Number(item.custom_retail_price).toFixed(2) : '0.00';
  // Turn the stored size run ("Preemie|Newborn|…") into one SKU per size. "unknown" = sizes with no code.
  const { variants, unknown } = sizeRunSkus(item.name, String(item.custom_size_run || '').split('|').filter(Boolean));
  // No usable sizes? Stop with a clear error.
  if (!variants.length) throw new Error(`Template ${item.name} has no size run with known size codes (${unknown.join(', ') || 'empty'})`);
  return {
    query: PRODUCT_SET_MUTATION,
    variables: {
      input: {
        title: item.item_name,
        // Always a draft: a person publishes it later.
        status: 'DRAFT',
